import {
  convertToModelMessages,
  createUIMessageStream,
  createUIMessageStreamResponse,
  streamText,
} from "ai";
import { deepseekChat } from "@/lib/deepseek";
import {
  codeSpecPatchSchema,
  codeSpecSchema,
  defaultCodeSpec,
  mergeCodeSpec,
  type CodeSpec,
  type CodeSpecPatch,
} from "@/lib/codegen-types";
import { buildCodegenSystemPrompt } from "@/lib/codegen-prompt";
import type { CodegenUIMessage } from "@/lib/chat-types";

export const maxDuration = 60;

export async function POST(req: Request) {
  try {
    if (!process.env.DEEPSEEK_API_KEY) {
      return Response.json(
        { error: "DEEPSEEK_API_KEY is not set. Add it to .env.local." },
        { status: 500 }
      );
    }

    const body = await req.json();
    const messages: CodegenUIMessage[] = body.messages ?? [];
    const parsedSpec = codeSpecSchema.safeParse(body.codeSpec);
    let currentSpec: CodeSpec = parsedSpec.success ? parsedSpec.data : defaultCodeSpec;

    const modelMessages = await convertToModelMessages(messages);

    const stream = createUIMessageStream<CodegenUIMessage>({
      execute: ({ writer }) => {
        const result = streamText({
          model: deepseekChat,
          system: buildCodegenSystemPrompt(currentSpec),
          messages: modelMessages,
          tools: {
            updateCodeSpec: {
              description:
                "Update the code architecture spec with nodes representing the agent's structure. Call this before writing the Python script.",
              inputSchema: codeSpecPatchSchema,
              execute: async (patch: CodeSpecPatch) => {
                currentSpec = mergeCodeSpec(currentSpec, patch);
                writer.write({
                  type: "data-codeSpec",
                  id: "code-spec",
                  data: currentSpec,
                });
                return { success: true, nodeCount: currentSpec.nodes.length };
              },
            },
          },
          onFinish: () => {
            writer.write({
              type: "data-codeSpec",
              id: "code-spec",
              data: currentSpec,
            });
          },
        });

        writer.merge(result.toUIMessageStream());
      },
      onError: (error) => {
        console.error("Codegen stream error:", error);
        return error instanceof Error ? error.message : "Code generation failed.";
      },
    });

    return createUIMessageStreamResponse({ stream });
  } catch (error) {
    console.error("Codegen route error:", error);
    return Response.json(
      {
        error:
          error instanceof Error
            ? error.message
            : "Failed to process code generation request.",
      },
      { status: 500 }
    );
  }
}

"use client";

import { useChat } from "@ai-sdk/react";
import { DefaultChatTransport } from "ai";
import { Check, Copy, Loader2, Sparkles, User, Bot } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import SyntaxHighlighter from "react-syntax-highlighter";
import { oneDark } from "react-syntax-highlighter/dist/esm/styles/prism";
import { ChatComposer } from "@/components/chat/chat-composer";
import { HudError } from "@/components/hud/hud-error";
import { HudPanel } from "@/components/hud/hud-panel";
import { ScrollArea } from "@/components/ui/scroll-area";
import type { CodeSpec } from "@/lib/codegen-types";
import type { CodegenUIMessage } from "@/lib/chat-types";

interface CodegenChatPanelProps {
  codeSpec: CodeSpec;
  onSpecUpdate: (spec: CodeSpec) => void;
  onError: (message: string) => void;
  onBuildingChange?: (building: boolean) => void;
  onCodeUpdate?: (code: string) => void;
}

const STARTER_PROMPTS = [
  "Read my Gmail every hour and email me a daily summary",
  "Monitor a URL for price changes and notify me via Slack",
  "Pull top HN posts every morning and send a digest email",
];

function extractPythonCode(text: string): string {
  const match = text.match(/```(?:python)?\n?([\s\S]*?)```/);
  return match ? match[1].trim() : text.trim();
}

function looksLikePython(text: string): boolean {
  return /\b(import|def |class |if __name__|os\.environ)\b/.test(text);
}

function CopyButton({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);

  async function handleCopy() {
    await navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  }

  return (
    <button
      type="button"
      onClick={handleCopy}
      className="flex items-center gap-1 rounded-md border border-white/[0.08] bg-surface-1/90 px-2 py-1 font-mono text-[9px] uppercase tracking-wider text-muted-foreground transition-colors hover:border-white/15 hover:text-foreground"
      aria-label="Copy code"
    >
      {copied ? (
        <>
          <Check className="size-3 text-green-400" />
          <span className="text-green-400">Copied</span>
        </>
      ) : (
        <>
          <Copy className="size-3" />
          Copy
        </>
      )}
    </button>
  );
}

function CodeBlock({ text, isStreaming }: { text: string; isStreaming?: boolean }) {
  const code = extractPythonCode(text);
  return (
    <div className="relative w-full overflow-hidden rounded-lg border border-white/[0.08]">
      <div className="flex items-center justify-between border-b border-white/[0.06] bg-surface-1/90 px-3 py-1.5">
        <span className="font-mono text-[9px] uppercase tracking-wider text-muted-foreground">
          Python
        </span>
        <div className="flex items-center gap-2">
          {isStreaming && (
            <span className="flex items-center gap-1 font-mono text-[9px] text-system">
              <span className="size-1.5 animate-pulse rounded-full bg-system" />
              Generating
            </span>
          )}
          <CopyButton text={code} />
        </div>
      </div>
      <div className="max-h-[420px] overflow-auto text-[12px]">
        <SyntaxHighlighter
          language="python"
          style={oneDark}
          customStyle={{
            margin: 0,
            background: "transparent",
            fontSize: "12px",
            lineHeight: "1.6",
          }}
          wrapLongLines={false}
        >
          {code}
        </SyntaxHighlighter>
      </div>
    </div>
  );
}

function ToolUpdatePart({ state }: { state?: string }) {
  const isDone = state === "output-available" || state === "output-error";
  return (
    <div
      className={`my-2 flex items-center gap-2 rounded-md border px-2.5 py-1.5 font-mono text-[10px] uppercase tracking-wider ${
        isDone
          ? "border-primary/20 bg-primary/[0.06] text-primary/80"
          : "border-system/25 bg-system/[0.06] text-system"
      }`}
    >
      <Sparkles className={`size-3 ${!isDone ? "animate-pulse" : ""}`} aria-hidden />
      {isDone ? "Architecture updated" : "Updating architecture…"}
    </div>
  );
}

export function CodegenChatPanel({
  codeSpec,
  onSpecUpdate,
  onError,
  onBuildingChange,
  onCodeUpdate,
}: CodegenChatPanelProps) {
  const [input, setInput] = useState("");
  const codeSpecRef = useRef(codeSpec);
  const scrollAnchorRef = useRef<HTMLDivElement>(null);

  codeSpecRef.current = codeSpec;

  const { messages, sendMessage, status, error, stop } = useChat<CodegenUIMessage>({
    transport: new DefaultChatTransport({
      api: "/api/codegen",
      prepareSendMessagesRequest: ({ messages, id }) => ({
        body: { messages, id, codeSpec: codeSpecRef.current },
      }),
    }),
    onData: (dataPart) => {
      if (dataPart.type === "data-codeSpec") {
        onSpecUpdate(dataPart.data);
      }
    },
    onError: (err) => {
      onError(err.message);
    },
    onFinish: (message) => {
      const textPart = message.parts.find((p) => p.type === "text");
      if (textPart && textPart.type === "text" && looksLikePython(textPart.text)) {
        onCodeUpdate?.(extractPythonCode(textPart.text));
      }
    },
  });

  const isBusy = status === "submitted" || status === "streaming";
  const lastMessage = messages.at(-1);
  const streamingAssistantId =
    isBusy && lastMessage?.role === "assistant" ? lastMessage.id : null;

  useEffect(() => {
    onBuildingChange?.(isBusy);
  }, [isBusy, onBuildingChange]);

  useEffect(() => {
    scrollAnchorRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, isBusy]);

  function submitPrompt(text: string) {
    const trimmed = text.trim();
    if (!trimmed || isBusy) return;
    sendMessage({ text: trimmed });
    setInput("");
  }

  return (
    <HudPanel tier={1} className="flex h-full min-h-[420px] flex-col">
      <div className="flex items-start justify-between gap-3 border-b border-white/[0.06] px-4 py-3">
        <div>
          <p className="hud-label">Input channel</p>
          <h2 className="mt-0.5 text-sm font-medium">Script generator</h2>
        </div>
        {isBusy ? (
          <span className="flex items-center gap-1.5 rounded-md border border-primary/25 bg-primary/[0.06] px-2 py-1 font-mono text-[9px] uppercase tracking-[0.14em] text-primary">
            <Loader2 className="size-3 animate-spin" />
            Processing
          </span>
        ) : messages.length > 0 ? (
          <span className="rounded-md border border-system/25 bg-system/[0.06] px-2 py-1 font-mono text-[9px] uppercase tracking-[0.14em] text-system">
            Ready
          </span>
        ) : null}
      </div>

      <ScrollArea className="flex-1 px-3">
        <div className="space-y-4 py-4">
          {messages.length === 0 && (
            <div className="space-y-3">
              <div className="rounded-xl border border-white/[0.06] bg-surface-2/40 px-4 py-4">
                <p className="text-sm font-medium text-foreground">
                  Describe your Python agent
                </p>
                <p className="mt-2 text-xs leading-relaxed text-muted-foreground">
                  Tell me what you want the script to do — I&apos;ll design the
                  architecture and generate a complete, runnable Python script.
                </p>
              </div>
              <div className="space-y-1.5">
                <p className="hud-label px-1">Quick prompts</p>
                {STARTER_PROMPTS.map((prompt) => (
                  <button
                    key={prompt}
                    type="button"
                    onClick={() => submitPrompt(prompt)}
                    disabled={isBusy}
                    className="w-full rounded-lg border border-white/[0.06] bg-surface-1 px-3 py-2.5 text-left text-xs leading-relaxed text-muted-foreground transition-all duration-200 hover:border-primary/25 hover:bg-surface-2/50 hover:text-foreground disabled:opacity-40"
                  >
                    {prompt}
                  </button>
                ))}
              </div>
            </div>
          )}

          {messages.map((message) => {
            const isUser = message.role === "user";
            const textParts = message.parts.filter((p) => p.type === "text");
            const toolParts = message.parts.filter((p) => p.type.startsWith("tool-"));
            const textContent = textParts
              .map((p) => (p.type === "text" ? p.text : ""))
              .join("")
              .trim();
            const isStreaming = message.id === streamingAssistantId;
            const isPythonCode = !isUser && looksLikePython(textContent);

            if (!textContent && toolParts.length === 0) return null;

            return (
              <div
                key={message.id}
                className={`flex gap-2.5 ${isUser ? "flex-row-reverse" : "flex-row"}`}
              >
                <div
                  className={`mt-0.5 flex size-6 shrink-0 items-center justify-center rounded-md border ${
                    isUser
                      ? "border-white/[0.08] bg-surface-3 text-muted-foreground"
                      : "border-primary/20 bg-primary/[0.08] text-primary"
                  }`}
                >
                  {isUser ? (
                    <User className="size-3.5" aria-hidden />
                  ) : (
                    <Bot className="size-3.5" aria-hidden />
                  )}
                </div>

                <div
                  className={`min-w-0 flex-1 text-sm leading-relaxed ${
                    isUser ? "flex justify-end" : ""
                  }`}
                >
                  {toolParts.map((part, index) => (
                    <ToolUpdatePart
                      key={index}
                      state={"state" in part ? String(part.state) : undefined}
                    />
                  ))}

                  {textContent && (
                    isPythonCode ? (
                      <CodeBlock text={textContent} isStreaming={isStreaming} />
                    ) : (
                      <div
                        className={`inline-block rounded-xl px-3.5 py-2.5 text-left ${
                          isUser
                            ? "border border-white/[0.08] bg-surface-3 text-foreground"
                            : "border border-white/[0.05] bg-surface-2/80 text-foreground/95"
                        }`}
                      >
                        <p className="whitespace-pre-wrap">{textContent}</p>
                        {isStreaming && !isUser && (
                          <span className="ml-0.5 inline-block size-1.5 animate-pulse rounded-full bg-primary align-middle" />
                        )}
                      </div>
                    )
                  )}
                </div>
              </div>
            );
          })}

          {error && <HudError message={error.message} />}
          <div ref={scrollAnchorRef} />
        </div>
      </ScrollArea>

      <div className="border-t border-white/[0.06]">
        <ChatComposer
          value={input}
          onChange={setInput}
          onSubmit={() => submitPrompt(input)}
          onStop={stop}
          isBusy={isBusy}
          placeholder="Describe your agent script or refine the current one…"
        />
      </div>
    </HudPanel>
  );
}

"use client";

import {
  Background,
  BackgroundVariant,
  Controls,
  MarkerType,
  ReactFlow,
  ReactFlowProvider,
  useReactFlow,
  type Edge,
  type Node,
} from "@xyflow/react";
import "@xyflow/react/dist/style.css";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { BoardNode, type BoardNodeData } from "@/components/board/board-node";
import { BoardToolbar } from "@/components/board/board-toolbar";
import { HudPanel } from "@/components/hud/hud-panel";
import {
  codeSpecSchema,
  defaultCodeSpec,
  isCodeSpecEmpty,
  type CodeFlowNode,
  type CodeSpec,
} from "@/lib/codegen-types";

interface CodegenGraphProps {
  spec: CodeSpec;
  isBuilding?: boolean;
}

const nodeTypes = { boardNode: BoardNode };

const ROW_Y: Record<CodeFlowNode["kind"], number> = {
  trigger: 80,
  input: 280,
  processor: 480,
  output: 680,
  dependency: 880,
};

const EDGE_COLORS: Record<string, string> = {
  "trigger-input": "#06b6d4",
  "input-processor": "#3b82f6",
  "processor-output": "#10b981",
};

function edgeColor(sourceKind: string, targetKind: string): string {
  return EDGE_COLORS[`${sourceKind}-${targetKind}`] ?? "rgba(255,255,255,0.25)";
}

const PLACEHOLDER_NODES: Node<BoardNodeData>[] = [
  {
    id: "ph-trigger",
    type: "boardNode",
    position: { x: 80, y: 80 },
    data: { label: "Trigger", subtitle: "Entry point", kind: "trigger", placeholder: true },
    draggable: false,
    selectable: false,
  },
  {
    id: "ph-input",
    type: "boardNode",
    position: { x: 80, y: 280 },
    data: { label: "Input", subtitle: "Data source", kind: "input", placeholder: true },
    draggable: false,
    selectable: false,
  },
  {
    id: "ph-output",
    type: "boardNode",
    position: { x: 80, y: 480 },
    data: { label: "Output", subtitle: "Delivery target", kind: "output", placeholder: true },
    draggable: false,
    selectable: false,
  },
];

const PLACEHOLDER_EDGES: Edge[] = [
  {
    id: "ph-e1",
    source: "ph-trigger",
    target: "ph-input",
    style: { stroke: "rgba(255,255,255,0.08)", strokeWidth: 1.5 },
    markerEnd: { type: MarkerType.ArrowClosed, color: "rgba(255,255,255,0.12)" },
  },
  {
    id: "ph-e2",
    source: "ph-input",
    target: "ph-output",
    style: { stroke: "rgba(255,255,255,0.08)", strokeWidth: 1.5, strokeDasharray: "6 4" },
    markerEnd: { type: MarkerType.ArrowClosed, color: "rgba(255,255,255,0.12)" },
  },
];

function buildGraphFromCodeSpec(
  spec: CodeSpec,
  seenNodeIds: Set<string>
): { nodes: Node<BoardNodeData>[]; edges: Edge[]; newCount: number } {
  const nodes: Node<BoardNodeData>[] = [];
  const edges: Edge[] = [];
  let newCount = 0;

  const byKind: Record<CodeFlowNode["kind"], CodeFlowNode[]> = {
    trigger: [],
    input: [],
    processor: [],
    output: [],
    dependency: [],
  };
  for (const node of spec.nodes) {
    byKind[node.kind].push(node);
  }

  const nodeKindMap: Record<string, CodeFlowNode["kind"]> = {};
  for (const node of spec.nodes) {
    nodeKindMap[node.id] = node.kind;
  }

  for (const node of spec.nodes) {
    const sameKind = byKind[node.kind];
    const idx = sameKind.indexOf(node);
    const x = 80 + idx * 300;
    const y = ROW_Y[node.kind];
    const isNew = !seenNodeIds.has(node.id);
    if (isNew) newCount++;

    nodes.push({
      id: node.id,
      type: "boardNode",
      position: { x, y },
      data: {
        label: node.label,
        subtitle: node.subtitle,
        detail: node.detail,
        kind: node.kind,
        isNew,
        animDelay: isNew ? idx * 80 : undefined,
      },
    });
  }

  // Canonical upstream row for automatic edges (when dependsOn is empty)
  const canonicalUpstream: Partial<Record<CodeFlowNode["kind"], CodeFlowNode["kind"]>> = {
    input: "trigger",
    processor: "input",
    output: "processor",
    dependency: "output",
  };

  for (const node of spec.nodes) {
    const sources: Array<{ id: string; kind: CodeFlowNode["kind"] }> =
      node.dependsOn.length > 0
        ? node.dependsOn
            .filter((depId) => nodeKindMap[depId])
            .map((depId) => ({ id: depId, kind: nodeKindMap[depId] }))
        : byKind[canonicalUpstream[node.kind] ?? "trigger"].map((n) => ({
            id: n.id,
            kind: n.kind,
          }));

    for (const src of sources) {
      const color = edgeColor(src.kind, node.kind);
      const isNew = !seenNodeIds.has(node.id) || !seenNodeIds.has(src.id);
      edges.push({
        id: `e-${src.id}-${node.id}`,
        source: src.id,
        target: node.id,
        animated: !isNew,
        className: isNew ? "edge-draw" : undefined,
        markerEnd: { type: MarkerType.ArrowClosed, color },
        style: { stroke: color, strokeWidth: 2, opacity: 0.65 },
      });
    }
  }

  return { nodes, edges, newCount };
}

function BoardCanvas({ spec, isBuilding }: CodegenGraphProps) {
  const seenNodeIdsRef = useRef<Set<string>>(new Set());
  const prevSpecKeyRef = useRef("");
  const [pulseKey, setPulseKey] = useState(0);
  const { fitView } = useReactFlow();

  const validSpec = useMemo(() => {
    const parsed = codeSpecSchema.safeParse(spec);
    return parsed.success ? parsed.data : defaultCodeSpec;
  }, [spec]);

  const isEmpty = isCodeSpecEmpty(validSpec);

  const { nodes, edges, newCount } = useMemo(() => {
    if (isEmpty) {
      return { nodes: PLACEHOLDER_NODES, edges: PLACEHOLDER_EDGES, newCount: 0 };
    }
    const graph = buildGraphFromCodeSpec(validSpec, seenNodeIdsRef.current);
    graph.nodes.forEach((node) => seenNodeIdsRef.current.add(node.id));
    return graph;
  }, [validSpec, isEmpty]);

  useEffect(() => {
    if (isEmpty) {
      seenNodeIdsRef.current.clear();
      prevSpecKeyRef.current = "";
      return;
    }
    const specKey = JSON.stringify(validSpec);
    if (specKey !== prevSpecKeyRef.current) {
      prevSpecKeyRef.current = specKey;
      if (newCount > 0) setPulseKey((k) => k + 1);
    }
  }, [validSpec, newCount, isEmpty]);

  useEffect(() => {
    const timer = setTimeout(() => {
      fitView({ padding: 0.2, duration: 300 });
    }, 50);
    return () => clearTimeout(timer);
